  draw(shift(i*transy)*((-75,0)--(-45,0)--(-60,26)--cycle));
  draw(shift(i*transy)*((0,0)--(30,0)--(15,26)--cycle));
  draw(shift(i*transy)*((75,0)--(105,0)--(90,26)--cycle));
  draw(shift(i*transy)*((-60,26)--(90,26)));
  draw(shift(i*transy)*((-45,0)--(75,0)));

