  dot("W", (-45,0) + i*transy, S);
  dot("R", (-60,26) + i*transy, N);
  dot((15,26) + i*transy);
  dot((0,0) + i*transy);
  dot((30,0) + i*transy);
  dot((90,26) + i*transy);
  dot((75,0) + i*transy);
  dot((105,0) + i*transy);
