dot("B", (15,26), N);
dot("R", (0,0), S);
dot("W", (30,0), S);

dot("W", (15,26) + (0,-70), N);
dot("R", (0,0) + (0,-70), S);
dot("B", (30,0) + (0,-70), S);

dot("W", (15,26) + (0,-2*70), N);
dot("B", (0,0) + (0,-2*70), S);
